def _attributed_or_refused(
    request: ReviewSourceContentRequest,
    inventory: ReviewSourceInventory,
    link: RealizationLink,
) -> SourceAdmission | ReviewRefusal:
    """Admit a measured-unchanged path that the comparison's recorded realization links, or refuse."""

    if not link.linked:
        if not link.determined:
            return _link_undetermined(request, inventory, link.detail)
        return _not_listed(request, inventory, link.detail)
    sides = " and ".join(link.linking_sides)
    return SourceAdmission(
        entry=None,
        path_bound="requested_generation",
        path_bound_detail=(
            f"the requested generation's own change set was measured ({inventory.listed_total} "
            "changed path(s)) and does not list this path, so the path is unchanged between the "
            "requested trees and is not an entry of that inventory"
        ),
        admission="attributed_unchanged",
        admission_detail=(
            f"a realization recorded in the comparison's {sides} knowledge is anchored at this "
            f"unchanged path ({link.detail}); it is opened as that realization's context at the "
            "requested trees and is not counted as a changed file"
        ),
    )

def recorded_realization_link(
    config: McpRuntimeConfig,
    request: ReviewSourceContentRequest,
    resolved: ReviewCandidateResolution,
) -> RealizationLink:
    """Whether a realization recorded in the requested comparison's knowledge links the path."""

    bound = _bound_knowledge(config, request, resolved)
    if isinstance(bound, RealizationLink):
        return bound
    if not _anchor_spelling(request.path):
        return RealizationLink(
            linking_sides=(),
            detail=(
                f"the requested spelling {request.path!r} is not exactly a path a recorded source "
                f"anchor can carry, so no realization in {bound.description} can link it and it is "
                "not matched to a nearby spelling"
            ),
        )
    try:
        namespace = review_namespace(
            bound.resolution.repository_id, bound.resolution.candidate_database
        )
    except KnowledgeStorageError as error:
        return RealizationLink(
            linking_sides=(),
            detail=(
                f"the namespace of {bound.description} could not be read from the record beside "
                f"its dataset ({error}), so neither half was read"
            ),
            determined=False,
        )
    readings = tuple(
        _side_reading(side, database, namespace, request.path) for side, database in _halves(bound)
    )
    linking: tuple[KnowledgeSide, ...] = tuple(
        reading.side for reading in readings if reading.state == "linked"
    )
    unread = any(reading.state == "unread" for reading in readings)
    return RealizationLink(
        linking_sides=linking,
        detail=_sentence(bound, readings),
        determined=bool(linking) or not unread,
    )

def _anchor_spelling(path: str) -> bool:
    """Whether ``path`` is, unchanged, a spelling the stored-anchor shape rule admits.

    The rule normalizes (it strips surrounding whitespace), so validating is not enough: the
    validated value must be the requested string itself, or a padded spelling would be answered with
    the link of the path it normalizes to.
    """

    try:
        return PathSeed(path=path).path == path
    except ValidationError:
        return False

def _bound_knowledge(
    config: McpRuntimeConfig,
    request: ReviewSourceContentRequest,
    resolved: ReviewCandidateResolution,
) -> _BoundKnowledge | RealizationLink:
    """The comparison the requested pair names, or the sentence that no knowledge is bound to it.

    The baseline has already been required to be the resolution's own, so only the after tree can
    differ; when it does, the pair is a superseded one and only a generation that recorded exactly
    that pair holds its knowledge.
    """

    if request.after_code_tree_id == resolved.candidate_code_tree_id:
        return _BoundKnowledge(
            resolution=resolved,
            description="the knowledge this leaf's review binds to the requested pair",
        )
    task_root = task_root_for_review(config, request.repository_id, request.master)
    for ref in reversed(read_generation_refs(task_root, resolved.leaf_id)):
        try:
            manifest = read_manifest(ref.directory / COMPARISON_MANIFEST_NAME)
        except KnowledgeStorageError:
            continue
        source = manifest.source
        if (source.baseline_code_tree_id, source.candidate_code_tree_id) != (
            request.before_code_tree_id,
            request.after_code_tree_id,
        ):
            continue
        reopened = resolve_committed_leaf_review(
            config,
            request.repository_id,
            request.master,
            request.leaf_id,
            generation_id=ref.generation_id,
        )
        if isinstance(reopened, ReviewRefusal):
            return RealizationLink(
                linking_sides=(),
                detail=(
                    f"the comparison generation {ref.generation_id} records the requested pair but "
                    f"could not be reopened ({reopened.detail}), so its knowledge was not read"
                ),
                determined=False,
            )
        return _BoundKnowledge(
            resolution=reopened,
            description=(
                f"the knowledge retained by comparison generation {ref.generation_id} (index "
                f"{ref.generation_index}), which recorded exactly the requested pair"
            ),
        )
    return RealizationLink(
        linking_sides=(),
        detail=(
            f"the requested pair is not the one this leaf's review binds now (it binds "
            f"{resolved.candidate_code_tree_id}), and no comparison generation this leaf published "
            "records exactly the requested pair, so no knowledge is bound to the requested "
            "comparison; the knowledge the leaf holds now is not substituted for it"
        ),
    )

export interface ReviewSourceExpansion {
  path: string;
  status: ReviewFileStatus | "unchanged";
  mode_change: boolean;
  language: string;
  before: ReviewSourceSide;
  after: ReviewSourceSide;
  before_code_tree_id: string;
  after_code_tree_id: string;
  currentness: "current" | "superseded" | "unmeasured";
  currentness_detail: string;
  path_bound: "requested_generation" | "leaf_change_set";
  path_bound_detail: string;
  admission: ReviewSourceAdmission;
  admission_detail: string;
  reference: string;
  command: string;
}

def _side_reading(side: KnowledgeSide, database: Path, namespace: str, path: str) -> _SideReading:
    """Ask one snapshot, by the read owner's exact claim-at-path query, whether it links ``path``.

    The snapshot's identity is resolved from the file first (namespace, schema generation), so a file
    that is not the dataset this comparison bound is ``unread`` with its cause rather than an absence.
    """

    if not database.is_file():
        return _SideReading(side, "unread", f"the {side} snapshot is absent at {database}")
    try:
        context = open_read_context(database, namespace)
        connection = open_read_only_database(database)
        try:
            rows = fetch_realizations_at_path(connection, context.repository_id, path)
        finally:
            connection.close()
    except (KnowledgeStorageError, OSError, ValueError, apsw.Error) as error:
        return _SideReading(
            side,
            "unread",
            f"the {side} snapshot at {database} could not be read ({type(error).__name__}: {error})",
        )
    if rows:
        return _SideReading(side, "linked", f"the {side} snapshot records a realization here")
    return _SideReading(side, "not_linked", f"the {side} snapshot records none")

def admit_source_path(
    config: McpRuntimeConfig,
    request: ReviewSourceContentRequest,
    resolved: ReviewCandidateResolution,
    inventory: ReviewSourceInventory,
) -> SourceAdmission | ReviewRefusal:
    """The measurement that admits the requested path, or the refusal that none does.

    The requested generation's own change set is asked first. When it was measured and does not list
    the path, the only remaining admission is a realization the comparison's knowledge records there.
    When it could not be measured, the change set this leaf's review publishes bounds the request
    instead, and no unchanged path is admitted at all.
    """

    entry = _entry_for(inventory, request.path)
    if entry is not None:
        return SourceAdmission(
            entry=entry,
            path_bound="requested_generation",
            path_bound_detail=(
                "the requested generation's own change set is the measurement that lists this path"
            ),
        )
    if inventory.state == "measured":
        return _attributed_or_refused(
            request, inventory, recorded_realization_link(config, request, resolved)
        )
    leaf = review_inventory(
        source_tree_side(resolved.baseline_code_tree_id, resolved.baseline_code_root),
        source_tree_side(resolved.candidate_code_tree_id, resolved.candidate_code_root),
    )
    if leaf.state == "measured" and _entry_for(leaf, request.path) is not None:
        return SourceAdmission(
            entry=None,
            path_bound="leaf_change_set",
            path_bound_detail=(
                f"the requested generation could not be measured ({inventory.detail}), so the "
                f"change set this leaf's review publishes -- its recorded baseline against the "
                f"candidate tree it binds now, {leaf.listed_total} changed path(s) -- is the "
                "measurement that lists this path"
            ),
        )
    return _unconfined(request, inventory, leaf)
